import{_ as n,o as a,c as t,aj as i}from"./chunks/framework.BdtAaXf2.js";const o=JSON.parse('{"title":"04-标识符和关键字","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/04-标识符和关键字/04-标识符和关键字.md","filePath":"仓颉入门到实战/04-标识符和关键字/04-标识符和关键字.md","lastUpdated":1734063565000,"__rawMarkdown":"# 04-标识符和关键字\\n\\n在仓颉语言中，我们用到自定义的变量、函数、类等元素的名称，都必须用到**标识符**。我们可以也将刚才的变量、函数、类等看成是我们\\n\\n可以在仓颉的这个世界中，自己给一些小朋友的名称。既然是要起名字，那么就有一些范围和一些限制。举个例子：我们不会给一个小孩\\n\\n起这样的名字：**卖75块钱眉笔的那个人**。这样的名称**不合法也不合理**\\n\\n\\n\\n## 标识符分类两类\\n\\n1. 普通标识符\\n2. 原始标识符\\n\\n\\n\\n## 普通标识符\\n\\n普通标识符的命名规则有如下两种\\n\\n1. 两个组成部分【AB】，【A】部分表示英文字母开头，【B】可以是英文字母、数字、和下划线\\n2. 三个组成部分【ABC】，【A】部分是一个或者多个下划线，【B】部分是英文字母，【C】部分可以是英文、数字、和下划线\\n\\n### 正例\\n\\n```c++\\npackage project1 // 标记当前项目的名称\\n\\nmain() {\\n    let abc = \\"小万1\\"\\n    let abc123 = \\"小万\\"\\n\\n    let _abc = \\"小万\\"\\n    let __ = \\"小万\\" // 两个下划线\\n\\n    let _abc123 = \\"小万\\"\\n}\\n```\\n\\n### 反例\\n\\n```c++\\n    let 123=\\"小万\\"\\n    let *123=\\"小万\\"\\n    let )123=\\"小万\\"\\n    let +123=\\"小万\\"\\n    let _=\\"小万\\"// 1个下划线  可以声明，但是在打印它时，会提示错误\\n```\\n\\n\\n\\n## 原始标识符\\n\\n原始标识符在实际开发中有的场景不多，主要用在仓颉关键字作为标识符的场景。\\n\\n可以理解为是让你可以定义一些特殊或者奇葩的名字。\\n\\n**原始标识符**是在**普通标识符**或**仓颉关键字**的外面加上一对反引号\\n\\n如\\n\\n```\\n`abc`\\n`if`\\n`else`\\n```\\n\\n### 正例\\n\\n```c++\\npackage project1 // 标记当前项目的名称\\n\\n// 结构体 if 作为奇葩的名字\\nstruct `if` {\\n    let name = \\"小万\\"\\n}\\n\\nmain() {\\n    let a: `if` = `if`()\\n    println(a.name)\\n\\n    println()\\n}\\n```\\n\\n\\n\\n\\n\\n## 关键字\\n\\n在仓颉语言中，它把一些名字作为的了仓颉的关键字或者保留字，意思是有特殊的用意，不能给我们开发者当成普通的标识符来使用。\\n\\n如 **let**\\n\\n```\\nlet let = \\"小万\\" // 此时  let 就是错误的使用方式 因为let 是关键字\\n```\\n\\n### 关键字一览\\n\\n| 关键字       | 关键字     | 关键字    |\\n| ------------ | ---------- | --------- |\\n| as           | abstract   | break     |\\n| Bool         | case       | catch     |\\n| class        | const      | continue  |\\n| Rune         | do         | else      |\\n| enum         | extend     | for       |\\n| func         | false      | finally   |\\n| foreign      | Float16    | Float32   |\\n| Float64      | if         | in        |\\n| is           | init       | import    |\\n| interface    | Int8       | Int16     |\\n| Int32        | Int64      | IntNative |\\n| let          | mut        | main      |\\n| macro        | match      | Nothing   |\\n| open         | operator   | override  |\\n| prop         | public     | package   |\\n| private      | protected  | quote     |\\n| redef        | return     | spawn     |\\n| super        | static     | struct    |\\n| synchronized | try        | this      |\\n| true         | type       | throw     |\\n| This         | unsafe     | Unit      |\\n| UInt8        | UInt16     | UInt32    |\\n| UInt64       | UIntNative | var       |\\n| VArray       | where      | while     |\\n\\n\\n\\n## 总结\\n\\n标识符的作用就是在告诉我们 怎么起名字是合理，大家按照正常起名字的意思来对待即可。"}'),e={name:"仓颉入门到实战/04-标识符和关键字/04-标识符和关键字.md"};function l(p,s,r,d,h,k){return a(),t("div",null,[...s[0]||(s[0]=[i("",29)])])}const u=n(e,[["render",l]]);export{o as __pageData,u as default};
